/* ============================================
   CreativeHub — Global Styles
   ============================================ */

/* CSS Variables */
:root {
  --color-primary: #F02D00;
  --color-dark: #171717;
  --color-white: #FFFFFF;
  --color-gray-50: #FAFAFA;
  --color-gray-100: #F5F5F5;
  --color-gray-200: #E5E5E5;
  --color-gray-300: #D4D4D4;
  --color-gray-400: #A3A3A3;
  --color-gray-500: #737373;
  --color-gray-600: #525252;
  --color-gray-700: #404040;
  --color-gray-800: #262626;
  --color-gray-900: #171717;
  --color-teal: #00C9A7;
  --color-green: #10B981;
  --color-accent: #00C9A7;

  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-display: 'DM Sans', var(--font-sans);

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;

  --shadow-sm: 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 12px 32px rgba(0,0,0,0.12);
  --shadow-xl: 0 24px 48px rgba(0,0,0,0.16);

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  color: var(--color-dark);
  background: var(--color-white);
  line-height: 1.6;
  min-height: 100vh;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-display);
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

.text-display {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 800;
  line-height: 1.1;
}

.text-title {
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 700;
}

.text-subtitle {
  font-size: 1.125rem;
  font-weight: 600;
}

.text-body {
  font-size: 1rem;
  line-height: 1.7;
  color: var(--color-gray-600);
}

.text-small {
  font-size: 0.875rem;
  line-height: 1.5;
}

.text-xs {
  font-size: 0.75rem;
  line-height: 1.4;
}

/* Layout Utilities */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.section {
  padding: 4rem 0;
}

.section-lg {
  padding: 6rem 0;
}

.flex {
  display: flex;
}

.flex-col {
  flex-direction: column;
}

.items-center {
  align-items: center;
}

.justify-between {
  justify-content: space-between;
}

.justify-center {
  justify-content: center;
}

.gap-2 { gap: 0.5rem; }
.gap-3 { gap: 0.75rem; }
.gap-4 { gap: 1rem; }
.gap-6 { gap: 1.5rem; }
.gap-8 { gap: 2rem; }

.grid {
  display: grid;
}

.grid-cols-1 { grid-template-columns: repeat(1, 1fr); }
.grid-cols-2 { grid-template-columns: repeat(2, 1fr); }
.grid-cols-3 { grid-template-columns: repeat(3, 1fr); }
.grid-cols-4 { grid-template-columns: repeat(4, 1fr); }

@media (min-width: 640px) {
  .sm\:grid-cols-2 { grid-template-columns: repeat(2, 1fr); }
  .sm\:grid-cols-3 { grid-template-columns: repeat(3, 1fr); }
}

@media (min-width: 768px) {
  .md\:grid-cols-2 { grid-template-columns: repeat(2, 1fr); }
  .md\:grid-cols-3 { grid-template-columns: repeat(3, 1fr); }
  .md\:grid-cols-4 { grid-template-columns: repeat(4, 1fr); }
  .md\:flex { display: flex; }
  .md\:hidden { display: none; }
  .md\:flex-row { flex-direction: row; }
}

@media (min-width: 1024px) {
  .lg\:grid-cols-3 { grid-template-columns: repeat(3, 1fr); }
  .lg\:grid-cols-4 { grid-template-columns: repeat(4, 1fr); }
  .lg\:grid-cols-5 { grid-template-columns: repeat(5, 1fr); }
  .lg\:flex { display: flex; }
  .lg\:hidden { display: none; }
  .lg\:col-span-3 { grid-column: span 3 / span 3; }
  .lg\:col-span-9 { grid-column: span 9 / span 9; }
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.75rem 1.5rem;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.btn-primary {
  background: var(--color-primary);
  color: var(--color-white);
}

.btn-primary:hover {
  background: #d12600;
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-dark {
  background: var(--color-dark);
  color: var(--color-white);
}

.btn-dark:hover {
  background: var(--color-gray-800);
  transform: translateY(-1px);
}

.btn-outline {
  background: transparent;
  color: var(--color-dark);
  border: 1.5px solid var(--color-gray-300);
}

.btn-outline:hover {
  border-color: var(--color-dark);
  background: var(--color-gray-50);
}

.btn-ghost {
  background: transparent;
  color: var(--color-gray-600);
}

.btn-ghost:hover {
  color: var(--color-dark);
  background: var(--color-gray-100);
}

.btn-lg {
  padding: 1rem 2rem;
  font-size: 1rem;
}

.btn-sm {
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
}

/* Cards */
.card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition-base);
  border: 1px solid var(--color-gray-200);
}

.card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.card-image {
  width: 100%;
  aspect-ratio: 16 / 10;
  object-fit: cover;
  background: linear-gradient(135deg, var(--color-gray-100), var(--color-gray-200));
}

.card-body {
  padding: 1.25rem;
}

/* Badges */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 0.25rem 0.625rem;
  font-size: 0.75rem;
  font-weight: 700;
  border-radius: 9999px;
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.badge-primary {
  background: var(--color-primary);
  color: var(--color-white);
}

.badge-accent {
  background: var(--color-accent);
  color: var(--color-dark);
}

.badge-dark {
  background: var(--color-dark);
  color: var(--color-white);
}

.badge-outline {
  background: transparent;
  color: var(--color-gray-600);
  border: 1px solid var(--color-gray-300);
}

/* ============================================
   Header
   ============================================ */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-gray-200);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.logo {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--color-dark);
  letter-spacing: -0.03em;
}

.logo span {
  color: var(--color-primary);
}

.nav-links {
  display: none;
  align-items: center;
  gap: 2rem;
}

.nav-links a {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-gray-700);
  transition: color var(--transition-fast);
}

.nav-links a:hover {
  color: var(--color-dark);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.search-btn {
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-md);
  color: var(--color-gray-600);
  transition: all var(--transition-fast);
}

.search-btn:hover {
  background: var(--color-gray-100);
  color: var(--color-dark);
}

.mobile-menu-btn {
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-md);
  color: var(--color-gray-700);
}

@media (min-width: 768px) {
  .nav-links {
    display: flex;
  }
  .mobile-menu-btn {
    display: none;
  }
}

/* Mobile Menu */
.mobile-menu {
  display: none;
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background: var(--color-white);
  border-bottom: 1px solid var(--color-gray-200);
  padding: 1rem 1.5rem;
  box-shadow: var(--shadow-lg);
}

.mobile-menu.open {
  display: block;
}

.mobile-menu a {
  display: block;
  padding: 0.75rem 0;
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-gray-700);
  border-bottom: 1px solid var(--color-gray-100);
}

.mobile-menu a:last-child {
  border-bottom: none;
}

/* ============================================
   Promo Banner
   ============================================ */
.promo-banner {
  background: linear-gradient(90deg, var(--color-primary), #ff5c33);
  color: var(--color-white);
  padding: 0.625rem 1.5rem;
  font-size: 0.875rem;
  font-weight: 600;
  position: relative;
}

.promo-banner-inner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  flex-wrap: wrap;
}

.promo-banner .countdown {
  font-variant-numeric: tabular-nums;
  font-weight: 700;
  background: rgba(255,255,255,0.2);
  padding: 0.25rem 0.625rem;
  border-radius: var(--radius-sm);
}

.promo-banner .close-btn {
  position: absolute;
  right: 1rem;
  top: 50%;
  transform: translateY(-50%);
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  color: var(--color-white);
  opacity: 0.8;
  transition: opacity var(--transition-fast);
}

.promo-banner .close-btn:hover {
  opacity: 1;
  background: rgba(255,255,255,0.15);
}

/* ============================================
   Carousels
   ============================================ */
.carousel-container {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform var(--transition-slow);
}

.carousel-slide {
  min-width: 100%;
  flex-shrink: 0;
}

.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-white);
  color: var(--color-dark);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: all var(--transition-fast);
}

.carousel-arrow:hover {
  background: var(--color-dark);
  color: var(--color-white);
}

.carousel-arrow.prev { left: 0.5rem; }
.carousel-arrow.next { right: 0.5rem; }

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 1.5rem;
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-gray-300);
  transition: all var(--transition-fast);
}

.carousel-dot.active {
  background: var(--color-dark);
  width: 24px;
  border-radius: 4px;
}

/* Horizontal scroll carousel (course cards) */
.scroll-carousel {
  position: relative;
}

.scroll-carousel-track {
  display: flex;
  gap: 1.25rem;
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  padding: 0.5rem 0.25rem 1.5rem;
  scrollbar-width: none;
}

.scroll-carousel-track::-webkit-scrollbar {
  display: none;
}

.scroll-carousel-item {
  scroll-snap-align: start;
  flex-shrink: 0;
  width: 280px;
}

.scroll-carousel-arrow {
  position: absolute;
  top: 35%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--color-white);
  color: var(--color-dark);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: all var(--transition-fast);
}

.scroll-carousel-arrow:hover {
  background: var(--color-dark);
  color: var(--color-white);
}

.scroll-carousel-arrow.prev { left: -1rem; }
.scroll-carousel-arrow.next { right: -1rem; }

@media (max-width: 767px) {
  .scroll-carousel-arrow { display: none; }
  .scroll-carousel-item { width: 260px; }
}

/* ============================================
   Course Cards
   ============================================ */
.course-card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--color-gray-200);
  transition: all var(--transition-base);
}

.course-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.course-card-image {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 10;
  background: linear-gradient(135deg, var(--color-gray-100), var(--color-gray-200));
  overflow: hidden;
}

.course-card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-slow);
}

.course-card:hover .course-card-image img {
  transform: scale(1.05);
}

.course-card-badges {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

.course-card-body {
  padding: 1rem;
}

.course-card-title {
  font-size: 0.9375rem;
  font-weight: 700;
  line-height: 1.4;
  color: var(--color-dark);
  margin-bottom: 0.375rem;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.course-card-instructor {
  font-size: 0.8125rem;
  color: var(--color-gray-500);
  margin-bottom: 0.625rem;
}

.course-card-meta {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.8125rem;
  color: var(--color-gray-500);
  margin-bottom: 0.625rem;
}

.course-card-meta .rating {
  color: var(--color-primary);
  font-weight: 700;
}

.course-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 0.5rem;
}

.course-card-price {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.course-card-price .current {
  font-size: 1rem;
  font-weight: 800;
  color: var(--color-dark);
}

.course-card-price .original {
  font-size: 0.8125rem;
  color: var(--color-gray-400);
  text-decoration: line-through;
}

.course-card-price .discount {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--color-primary);
  background: rgba(240,45,0,0.08);
  padding: 0.125rem 0.375rem;
  border-radius: var(--radius-sm);
}

/* ============================================
   Accordion
   ============================================ */
.accordion-item {
  border-bottom: 1px solid var(--color-gray-200);
}

.accordion-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 0;
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-dark);
  text-align: left;
  transition: color var(--transition-fast);
}

.accordion-trigger:hover {
  color: var(--color-primary);
}

.accordion-trigger .icon {
  width: 20px;
  height: 20px;
  transition: transform var(--transition-base);
  flex-shrink: 0;
}

.accordion-item.open .accordion-trigger .icon {
  transform: rotate(180deg);
}

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow), padding var(--transition-slow);
}

.accordion-item.open .accordion-content {
  max-height: 500px;
  padding-bottom: 1.25rem;
}

.accordion-content p {
  color: var(--color-gray-600);
  line-height: 1.7;
}

/* ============================================
   Footer
   ============================================ */
.footer {
  background: var(--color-gray-50);
  border-top: 1px solid var(--color-gray-200);
  padding-top: 3rem;
  padding-bottom: 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2rem;
}

.footer-column h4 {
  font-size: 0.875rem;
  font-weight: 700;
  color: var(--color-dark);
  margin-bottom: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.footer-column ul li {
  margin-bottom: 0.5rem;
}

.footer-column ul li a {
  font-size: 0.875rem;
  color: var(--color-gray-600);
  transition: color var(--transition-fast);
}

.footer-column ul li a:hover {
  color: var(--color-primary);
}

.footer-bottom {
  margin-top: 3rem;
  padding-top: 2rem;
  border-top: 1px solid var(--color-gray-200);
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  align-items: center;
  text-align: center;
}

.footer-bottom .apps {
  display: flex;
  gap: 0.75rem;
}

.app-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  background: var(--color-dark);
  color: var(--color-white);
  border-radius: var(--radius-md);
  font-size: 0.8125rem;
  font-weight: 600;
}

.footer-bottom .legal {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 1rem;
}

.footer-bottom .legal a {
  font-size: 0.8125rem;
  color: var(--color-gray-500);
  transition: color var(--transition-fast);
}

.footer-bottom .legal a:hover {
  color: var(--color-dark);
}

.footer-bottom .languages {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.5rem 1rem;
}

.footer-bottom .languages a {
  font-size: 0.8125rem;
  color: var(--color-gray-500);
}

.footer-bottom .languages a:hover {
  color: var(--color-primary);
}

.footer-bottom .languages a.active {
  color: var(--color-dark);
  font-weight: 600;
}

/* Mobile footer accordion */
.footer-accordion-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 0.75rem 0;
  font-size: 0.875rem;
  font-weight: 700;
  color: var(--color-dark);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.footer-accordion-trigger .icon {
  transition: transform var(--transition-base);
}

.footer-column.collapsed .footer-accordion-trigger .icon {
  transform: rotate(-90deg);
}

.footer-column .footer-links {
  overflow: hidden;
  transition: max-height var(--transition-slow);
}

.footer-column.collapsed .footer-links {
  max-height: 0;
}

@media (min-width: 768px) {
  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }
  .footer-accordion-trigger .icon {
    display: none;
  }
  .footer-column.collapsed .footer-links {
    max-height: none;
  }
}

@media (min-width: 1024px) {
  .footer-grid {
    grid-template-columns: repeat(6, 1fr);
  }
}

/* ============================================
   Pricing
   ============================================ */
.pricing-toggle {
  display: inline-flex;
  background: var(--color-gray-100);
  border-radius: var(--radius-xl);
  padding: 0.25rem;
  position: relative;
}

.pricing-toggle button {
  padding: 0.625rem 1.5rem;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-xl);
  color: var(--color-gray-600);
  transition: all var(--transition-fast);
  position: relative;
  z-index: 1;
}

.pricing-toggle button.active {
  background: var(--color-white);
  color: var(--color-dark);
  box-shadow: var(--shadow-sm);
}

.pricing-card {
  background: var(--color-white);
  border: 2px solid var(--color-gray-200);
  border-radius: var(--radius-xl);
  padding: 2rem;
  transition: all var(--transition-base);
}

.pricing-card.featured {
  border-color: var(--color-primary);
  box-shadow: 0 0 0 4px rgba(240,45,0,0.08);
}

.pricing-card:hover {
  box-shadow: var(--shadow-lg);
}

.pricing-card .price {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--color-dark);
  line-height: 1;
}

.pricing-card .price span {
  font-size: 1rem;
  font-weight: 500;
  color: var(--color-gray-500);
}

.pricing-card .savings {
  display: inline-flex;
  background: var(--color-accent);
  color: var(--color-dark);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.25rem 0.625rem;
  border-radius: var(--radius-sm);
  margin-top: 0.5rem;
}

/* ============================================
